-- 0581 · THE SHARED DELETE (QUEUE §3 A, the maintainer 2 Oct 2026): "Postgres ON DELETE CASCADE rules on the foreign keys,
-- one shared delete route driven by a list of record types, one shared confirm dialog."
--
-- Until now the whole API had ONE delete route; every foreign key from a record type to the things that belong
-- to it was RESTRICT/NO ACTION, so no record could be removed. This migration changes the DATABASE's rules so
-- that deleting a record takes what it OWNS with it, and leaves everything that merely points at it alone:
--   · ON DELETE CASCADE   — rows that are meaningless without the parent (a person's invoices, messages,
--                           balances; a booking's participants; a template's requirements; join rows)
--   · ON DELETE SET NULL  — a "used by" pointer whose owner must survive (the credit a booking consumed, the
--                           document a subscription was created from, the estimate an invoice came from)
--   · left RESTRICT       — authorship (created_by, invited_by, host_id …: deleting an author must be REFUSED,
--                           not delete their work) and "in use" links (a unit/location/segment/service/package/
--                           plan that records still point at is refused, with the count, not emptied)
--   · audit_entry.actor_user_id FK DROPPED — the audit log is permanent history; its actor id stays as a
--                           plain uuid after the person is deleted (a CHECK forbids nulling it)
-- The list was GENERATED from the catalog (scripts/gen-delete-cascades.mjs) starting at the deletable record
-- types, then reviewed line by line. Idempotent: a constraint already in the target shape is skipped.
--
-- ★ THE THREE DB GUARDS THAT STOOD IN FRONT OF "DELETE SIGNED DOCUMENTS" now honour an explicit, audited
--   override — `keystone.record_delete_reason`, set ONLY by the shared delete route (src/records/delete.mjs) for
--   an Owner/Admin: an executed/declined document, its signature records, and an e-sign disclosure acceptance.
--   the maintainer's QUEUE §3 A lists "documents (draft/sent/signed)" and B needs signed test documents gone; the deletion
--   itself is written to audit_entry (record.deleted, with what cascaded) and cannot be erased.
--   `protected_real_client` (Example Client) is NOT bypassed — that guard keeps its own, separate reason GUC.
--
-- Also: DELETE grants app_rw lacked on twelve record tables.

CREATE OR REPLACE FUNCTION pg_temp.dc_set_fk(p_table regclass, p_name text, p_def text) RETURNS void
LANGUAGE plpgsql AS $f$
DECLARE v_cur text;
BEGIN
  SELECT pg_get_constraintdef(oid) INTO v_cur FROM pg_constraint WHERE conrelid = p_table AND conname = p_name;
  IF v_cur IS NULL THEN RAISE NOTICE '0581: % has no constraint % — skipped', p_table, p_name; RETURN; END IF;
  IF v_cur = p_def THEN RETURN; END IF;
  EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I, ADD CONSTRAINT %I %s', p_table, p_name, p_name, p_def);
END $f$;

CREATE OR REPLACE FUNCTION pg_temp.dc_drop_fk(p_table regclass, p_name text) RETURNS void
LANGUAGE plpgsql AS $f$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = p_table AND conname = p_name) THEN
    EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I', p_table, p_name);
  END IF;
END $f$;

