-- ── the three immutability guards: honour the delete route's audited override ────────────────────────────────
CREATE OR REPLACE FUNCTION keystone.document_instance_terminal_no_delete() RETURNS trigger
LANGUAGE plpgsql AS $f$
BEGIN
  IF nullif(btrim(coalesce(current_setting('keystone.record_delete_reason', true), '')), '') IS NOT NULL THEN
    RETURN OLD;   -- the shared delete route, for an Owner/Admin, audited (record.deleted)
  END IF;
  IF OLD.state IN ('executed', 'declined') THEN
    RAISE EXCEPTION
      'an % instrument is never deleted — its signature records reference it and its snapshot is the '
      'record of what was agreed. Void it instead.', OLD.state
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN OLD;
END;
$f$;

CREATE OR REPLACE FUNCTION keystone.esign_acceptance_no_delete() RETURNS trigger
LANGUAGE plpgsql AS $f$
BEGIN
  IF nullif(btrim(coalesce(current_setting('keystone.record_delete_reason', true), '')), '') IS NOT NULL THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION
    'an electronic-records disclosure acceptance is never deleted — instruments executed while it was '
    'live quote it. Set withdrawn_at to end it.'
    USING ERRCODE = 'check_violation';
END;
$f$;

CREATE OR REPLACE FUNCTION keystone.signature_record_is_immutable() RETURNS trigger
LANGUAGE plpgsql AS $f$
BEGIN
  IF nullif(btrim(coalesce(current_setting('keystone.record_delete_reason', true), '')), '') IS NOT NULL THEN
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;   -- delete, or the signer_uid SET NULL of a deleted person
  END IF;
  RAISE EXCEPTION
    'a signature record is evidence and is never % — it states who signed, when, and in what order, '
    'and an instrument already executed quotes it. To correct one, void the instrument and issue a '
    'new one.', CASE TG_OP WHEN 'DELETE' THEN 'deleted' ELSE 'changed' END
    USING ERRCODE = 'check_violation';
END;
$f$;

-- ── DELETE grants app_rw lacked on record tables the shared delete route removes from ───────────────────────
GRANT DELETE ON keystone.automation_config, keystone.credit_note, keystone.document_clause, keystone.estimate,
  keystone.gift_card, keystone.landing_page, keystone.location, keystone.loyalty_reward, keystone.loyalty_rule,
  keystone.payment_link, keystone.refund, keystone.unit TO app_rw;

-- ── the audit action the delete writes ──────────────────────────────────────────────────────────────────────
ALTER TABLE keystone.audit_action NO FORCE ROW LEVEL SECURITY;
INSERT INTO keystone.audit_action (key) VALUES ('record.deleted') ON CONFLICT (key) DO NOTHING;
ALTER TABLE keystone.audit_action FORCE ROW LEVEL SECURITY;
